package infra

import (
	"context"
	"fmt"
	"time"

	"github.com/redis/go-redis/v9"
)

// StreamMessage represents a message consumed from a Redis Stream.
type StreamMessage struct {
	// ID is the Redis stream message ID (auto-generated by XADD).
	ID string
	// MsgID is the business message ID extracted from the payload.
	MsgID string
	// Body is the raw JSON payload from the stream message.
	Body []byte
}

// StreamQueue is a reliable message queue with consumer groups,
// acknowledgements, and pending message claiming (for zombie recovery).
//
// Two streams are used in the system:
//   - cg:stream:conversation / cg:workers → async conversation pipeline
//   - cg:stream:task / cg:executors → subtask pipeline (Phase 3)
//
// Consumer groups ensure at-least-once delivery with automatic load distribution
// across multiple worker instances.
type StreamQueue interface {
	// Push adds a message to the stream (XADD).
	Push(ctx context.Context, msgID string, body []byte) error

	// Receive blocks until a message is available (XREADGROUP with BLOCK).
	// Returns nil, nil if no message arrives within the block timeout.
	Receive(ctx context.Context) (*StreamMessage, error)

	// Ack acknowledges a message, removing it from the consumer group's pending list (XACK).
	Ack(ctx context.Context, streamMsgID string) error

	// Requeue pushes a message back to the stream for retry. Unlike the original,
	// this creates a new stream entry — the old one stays in pending until ACKed or claimed.
	Requeue(ctx context.Context, msgID string, body []byte) error

	// ClaimPending claims messages that have been idle (pending without ACK)
	// longer than minIdle. Used by the zombie recovery scanner to take over
	// abandoned work from crashed workers.
	ClaimPending(ctx context.Context, minIdle time.Duration) ([]*StreamMessage, error)
}

// RedisStreamQueue implements StreamQueue on top of Redis Streams with
// consumer groups. Each instance is bound to a specific stream key,
// consumer group, and consumer name (worker ID).
//
// Consumer groups are auto-created on construction via XGroupCreateMkStream
// (idempotent — succeeds if group already exists).
type RedisStreamQueue struct {
	rdb       *redis.Client // Redis 客户端
	streamKey string        // stream key，如 "cg:stream:conversation"
	group     string        // consumer group 名，如 "cg:workers"
	consumer  string        // consumer 名（也是 worker ID）
	blockTime time.Duration // XREADGROUP 阻塞超时，默认 5s
}

// NewRedisStreamQueue creates a Redis-backed StreamQueue. The consumer group
// is created automatically on construction if it doesn't exist (using MKSTREAM).
func NewRedisStreamQueue(rdb *redis.Client, streamKey, group, consumer string) *RedisStreamQueue {
	sq := &RedisStreamQueue{
		rdb:       rdb,
		streamKey: streamKey,
		group:     group,
		consumer:  consumer,
		blockTime: 5 * time.Second,
	}

	// Idempotent group creation — fails if group exists, which is fine
	_ = rdb.XGroupCreateMkStream(context.Background(), streamKey, group, "0").Err()

	return sq
}

// Push adds a message to the stream using XADD.
func (sq *RedisStreamQueue) Push(ctx context.Context, msgID string, body []byte) error {
	// Wrap the body with the msg_id for identification
	vals := map[string]interface{}{
		"msg_id": msgID,
		"body":   string(body),
	}
	_, err := sq.rdb.XAdd(ctx, &redis.XAddArgs{
		Stream: sq.streamKey,
		Values: vals,
	}).Result()
	if err != nil {
		return fmt.Errorf("stream_queue: push: %w", err)
	}
	return nil
}

// Receive blocks until a message is available, reading as a consumer group member.
// Uses XREADGROUP with BLOCK to efficiently wait for new messages.
func (sq *RedisStreamQueue) Receive(ctx context.Context) (*StreamMessage, error) {
	streams, err := sq.rdb.XReadGroup(ctx, &redis.XReadGroupArgs{
		Group:    sq.group,
		Consumer: sq.consumer,
		Streams:  []string{sq.streamKey, ">"}, // ">" means new messages only
		Count:    1,
		Block:    sq.blockTime,
	}).Result()
	if err != nil {
		if err == redis.Nil {
			return nil, nil // No message available within block time
		}
		return nil, fmt.Errorf("stream_queue: receive: %w", err)
	}

	if len(streams) == 0 || len(streams[0].Messages) == 0 {
		return nil, nil
	}

	msg := streams[0].Messages[0]
	msgID, _ := msg.Values["msg_id"].(string)
	body, _ := msg.Values["body"].(string)

	return &StreamMessage{
		ID:    msg.ID,
		MsgID: msgID,
		Body:  []byte(body),
	}, nil
}

// Ack acknowledges a message, removing it from the pending list via XACK.
func (sq *RedisStreamQueue) Ack(ctx context.Context, streamMsgID string) error {
	_, err := sq.rdb.XAck(ctx, sq.streamKey, sq.group, streamMsgID).Result()
	if err != nil {
		return fmt.Errorf("stream_queue: ack: %w", err)
	}
	return nil
}

// Requeue pushes a message back to the stream (used by zombie recovery for retry).
// This creates a new stream entry — the old one remains in pending until ACKed
// or claimed.
func (sq *RedisStreamQueue) Requeue(ctx context.Context, msgID string, body []byte) error {
	return sq.Push(ctx, msgID, body)
}

// ClaimPending claims messages from the pending list that have been idle longer
// than minIdle. Used by the zombie recovery scanner to take over abandoned work.
func (sq *RedisStreamQueue) ClaimPending(ctx context.Context, minIdle time.Duration) ([]*StreamMessage, error) {
	// First get pending messages
	pending, err := sq.rdb.XPendingExt(ctx, &redis.XPendingExtArgs{
		Stream: sq.streamKey,
		Group:  sq.group,
		Start:  "-",
		End:    "+",
		Count:  100,
		Idle:   minIdle,
	}).Result()
	if err != nil && err != redis.Nil {
		return nil, fmt.Errorf("stream_queue: xpending: %w", err)
	}
	if len(pending) == 0 {
		return nil, nil
	}

	// Collect message IDs
	ids := make([]string, len(pending))
	for i, p := range pending {
		ids[i] = p.ID
	}

	// Claim them
	claimed, err := sq.rdb.XClaim(ctx, &redis.XClaimArgs{
		Stream:   sq.streamKey,
		Group:    sq.group,
		Consumer: sq.consumer,
		MinIdle:  minIdle,
		Messages: ids,
	}).Result()
	if err != nil {
		return nil, fmt.Errorf("stream_queue: xclaim: %w", err)
	}

	var msgs []*StreamMessage
	for _, c := range claimed {
		msgID, _ := c.Values["msg_id"].(string)
		body, _ := c.Values["body"].(string)
		msgs = append(msgs, &StreamMessage{
			ID:    c.ID,
			MsgID: msgID,
			Body:  []byte(body),
		})
	}
	return msgs, nil
}
